# Microsoft Graph API Email Functions (OAuth2)
# ============================================================

class GraphEmailMessage:
    """Adapter to make a Graph API message dict behave like email.message.EmailMessage for header access"""
    def __init__(self, graph_msg):
        self._msg = graph_msg
        from_info = graph_msg.get('from', {}).get('emailAddress', {})
        from_str = from_info.get('address', 'Unknown')
        from_name = from_info.get('name', '')
        if from_name:
            from_str = f"{from_name} <{from_info.get('address', '')}>"
        self._headers = {
            'From': from_str,
            'Subject': graph_msg.get('subject', 'No Subject'),
            'Date': graph_msg.get('receivedDateTime', ''),
        }
        self._graph_id = graph_msg.get('id', '')

    def get(self, key, default=None):
        return self._headers.get(key, default)

    def walk(self):
        return iter([])


def _get_graph_access_token():
    """Get OAuth2 access token using Client Credentials flow via MSAL"""
    authority = f"https://login.microsoftonline.com/{MS_TENANT_ID}"
    app = msal.ConfidentialClientApplication(
        MS_CLIENT_ID,
        authority=authority,
        client_credential=MS_CLIENT_SECRET,
    )
    result = app.acquire_token_for_client(scopes=["https://graph.microsoft.com/.default"])
    if "access_token" in result:
        return result["access_token"]
    raise Exception(f"Graph auth failed: {result.get('error_description', result.get('error', 'Unknown'))}")


def fetch_emails_from_graph():
    """
    Fetch emails using Microsoft Graph API (OAuth2 Client Credentials).
    Returns dict with 'emails' list and 'diagnostics' info.
    """
    diagnostics = {
        'method': 'graph_api',
        'imap_server': 'graph.microsoft.com',
        'email_account': PO_EMAIL_ADDRESS,
        'provider': 'Microsoft Graph API (OAuth2)',
        'connected': False,
        'login_success': False,
        'total_in_inbox': 0,
        'already_processed': 0,
        'unprocessed_checked': 0,
        'with_attachments': 0,
        'without_attachments': 0,
        'error': None
    }
    emails_out = []

    try:
        print(f"  Authenticating with Microsoft Graph API...")
        token = _get_graph_access_token()
        diagnostics['connected'] = True
        diagnostics['login_success'] = True
        print(f"  ✓ Graph API authentication successful")
        headers = {'Authorization': f'Bearer {token}'}

        # Get processed UIDs from database
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute("SELECT email_uid FROM email_processing_log")
        processed_uids = {row[0] for row in c.fetchall()}
        conn.close()
        diagnostics['already_processed'] = len(processed_uids)

        # Fetch messages with attachments
        # Note: Graph API doesn't support $filter + $orderby together on messages
        # so we fetch filtered results and sort client-side
        # Use $expand=attachments($select=id,name,contentType) to avoid per-message API calls
        user_email = PO_EMAIL_ADDRESS
        url = f"https://graph.microsoft.com/v1.0/users/{user_email}/messages"
        params = {
            '$filter': 'hasAttachments eq true',
            '$top': 50,
            '$select': 'id,subject,from,receivedDateTime,hasAttachments',
            '$expand': 'attachments($select=id,name,contentType,size)'
        }

        all_messages = []
        while url:
            response = http_requests.get(url, headers=headers, params=params)
            response.raise_for_status()
            data = response.json()
            all_messages.extend(data.get('value', []))
            url = data.get('@odata.nextLink', None)
            params = None  # nextLink includes params already

        # Sort newest first
        all_messages.sort(key=lambda m: m.get('receivedDateTime', ''), reverse=True)

        diagnostics['total_in_inbox'] = len(all_messages)
        print(f"  📧 Found {len(all_messages)} emails with attachments via Graph API")
        print(f"     Already processed: {len(processed_uids)}")

        for msg_data in all_messages:
            msg_id = msg_data['id']
            subject = msg_data.get('subject', 'No Subject')

            if msg_id in processed_uids:
                continue

            diagnostics['unprocessed_checked'] += 1

            # Check for PDF attachments using expanded data (no extra API call needed)
            att_list = msg_data.get('attachments', [])
            has_pdf = any(
                a.get('name', '').lower().endswith('.pdf') or
                a.get('contentType', '') == 'application/pdf'
                for a in att_list
            )

            if has_pdf:
                wrapped_msg = GraphEmailMessage(msg_data)
                emails_out.append((msg_id, wrapped_msg))
                diagnostics['with_attachments'] += 1
                print(f"  ✓ Found email with PDF attachment(s): {subject[:60]}")
            else:
                diagnostics['without_attachments'] += 1
                print(f"  ⊘ Skipped (no PDF attachments): {subject[:60]}")

        print(f"  ✓ Graph API complete - {len(emails_out)} new emails with PDF attachments")
        return {'emails': emails_out, 'diagnostics': diagnostics}

    except Exception as e:
        error_msg = str(e)
        # Try to get the actual error response body from Microsoft
        detail = ''
        if hasattr(e, 'response') and e.response is not None:
            try:
                err_body = e.response.json()
                err_info = err_body.get('error', {})
                detail = f" - {err_info.get('code', '')}: {err_info.get('message', '')}"
            except Exception:
                detail = f" - HTTP {e.response.status_code}: {e.response.text[:200]}"

        print(f"  ✗ Graph API error: {error_msg}{detail}")

        if 'acquire_token' in error_msg or 'auth' in error_msg.lower():
            diagnostics['error'] = f'Graph API authentication failed: {error_msg}{detail}'
        elif 'MailboxNotFound' in error_msg or '404' in error_msg or 'MailboxNotFound' in detail:
            diagnostics['error'] = f'Mailbox not found for {PO_EMAIL_ADDRESS}. Check the email address and ensure Mail.Read permission with admin consent is granted.{detail}'
        elif '403' in error_msg or 'Forbidden' in error_msg or '403' in detail or 'Authorization' in detail:
            diagnostics['error'] = f'Access denied. Make sure Mail.Read APPLICATION permission (not Delegated) is added AND admin consent is granted in Azure.{detail}'
        else:
            diagnostics['error'] = f'Graph API error: {error_msg}{detail}'
        import traceback
        traceback.print_exc()
        return {'emails': [], 'diagnostics': diagnostics}


def extract_attachments_from_graph_message(msg_id, token=None):
    """
    Download attachments from a Graph API message.
    Returns list of (filename, file_content_bytes) tuples - same format as extract_attachments_from_email.
    """
    if token is None:
        token = _get_graph_access_token()

    headers = {'Authorization': f'Bearer {token}'}
    url = f"https://graph.microsoft.com/v1.0/users/{PO_EMAIL_ADDRESS}/messages/{msg_id}/attachments"
    response = http_requests.get(url, headers=headers)
    response.raise_for_status()

    attachments = []
    for att in response.json().get('value', []):
        if att.get('@odata.type') == '#microsoft.graph.fileAttachment':
            filename = att.get('name', 'unnamed')
            content_bytes = base64.b64decode(att['contentBytes'])
            attachments.append((filename, content_bytes))
            print(f"    📎 Downloaded attachment: {filename} ({len(content_bytes)} bytes)")
        elif att.get('@odata.type') == '#microsoft.graph.itemAttachment':
            # Forwarded email attachment - check for nested file attachments
            item_att_url = f"{url}/{att['id']}?$expand=microsoft.graph.itemAttachment/item"
            item_resp = http_requests.get(item_att_url, headers=headers)
            if item_resp.ok:
                item_data = item_resp.json()
                nested_item = item_data.get('item', {})
                if nested_item.get('attachments'):
                    for nested_att in nested_item['attachments']:
                        if nested_att.get('@odata.type') == '#microsoft.graph.fileAttachment':
                            filename = nested_att.get('name', 'unnamed')
                            content_bytes = base64.b64decode(nested_att['contentBytes'])
                            attachments.append((filename, content_bytes))
                            print(f"    📎 Downloaded nested attachment: {filename} ({len(content_bytes)} bytes)")

    return attachments


def fetch_emails():
    """Unified email fetcher - tries Graph API first, falls back to IMAP"""
    print(f"  MS_GRAPH_ENABLED={MS_GRAPH_ENABLED} (MSAL={MSAL_AVAILABLE}, TENANT={'set' if MS_TENANT_ID else 'empty'}, CLIENT={'set' if MS_CLIENT_ID else 'empty'}, SECRET={'set' if MS_CLIENT_SECRET else 'empty'})")

    if MS_GRAPH_ENABLED:
        print("📧 Using Microsoft Graph API (OAuth2)...")
        result = fetch_emails_from_graph()
        result['diagnostics']['source'] = 'graph_api'
        # Always return Graph API result when it's configured - don't silently fall back to IMAP
        return result
    else:
        print("  ⚠ Graph API not enabled, using IMAP")

    if PO_EMAIL_ADDRESS and PO_EMAIL_PASSWORD:
        print("📧 Using IMAP...")
        result = fetch_emails_from_imap()
        result['diagnostics']['source'] = 'imap'
        return result

    return {
        'emails': [],
        'diagnostics': {
            'error': 'No email credentials configured. Set MS_TENANT_ID/MS_CLIENT_ID/MS_CLIENT_SECRET for Graph API, or PO_EMAIL_ADDRESS/PO_EMAIL_PASSWORD for IMAP.',
            'source': 'none'
        }
    }


def fetch_emails_from_imap():
    """
    Connect to IMAP server and fetch unprocessed emails with attachments
    Returns dict with 'emails' list and 'diagnostics' info, or raises exception on failure
    """
    if not PO_EMAIL_MONITORING_ENABLED:
        print("⚠ Email monitoring not enabled - set PO_EMAIL_ADDRESS and PO_EMAIL_PASSWORD")
        return {'emails': [], 'diagnostics': {'error': 'Email monitoring not enabled - PO_EMAIL_ADDRESS or PO_EMAIL_PASSWORD not set'}}

    emails = []
    diagnostics = {
        'imap_server': PO_EMAIL_IMAP_SERVER,
        'email_account': PO_EMAIL_ADDRESS,
        'provider': PO_EMAIL_PROVIDER,
        'connected': False,
        'login_success': False,
        'total_in_inbox': 0,
        'already_processed': 0,
        'unprocessed_checked': 0,
        'with_attachments': 0,
        'without_attachments': 0,
        'error': None
    }

    try:
        mail = imaplib.IMAP4_SSL(PO_EMAIL_IMAP_SERVER, PO_EMAIL_IMAP_PORT)
        diagnostics['connected'] = True
        print(f"✓ Connected to IMAP server: {PO_EMAIL_IMAP_SERVER}")

        mail.login(PO_EMAIL_ADDRESS, PO_EMAIL_PASSWORD)
        diagnostics['login_success'] = True
        print(f"✓ Login successful: {PO_EMAIL_ADDRESS}")

        # Select INBOX
        status, mailbox_data = mail.select('INBOX')
        if status == 'OK':
            inbox_count = int(mailbox_data[0].decode()) if mailbox_data[0] else 0
            diagnostics['total_in_inbox'] = inbox_count
            print(f"📧 INBOX contains {inbox_count} messages")

        # Get already processed email UIDs
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute("SELECT email_uid FROM email_processing_log")
        processed_uids = {row[0] for row in c.fetchall()}
        conn.close()
        diagnostics['already_processed'] = len(processed_uids)

        # Use IMAP UID commands for stable identifiers (sequence numbers shift when emails are deleted)
        status, uid_data = mail.uid('search', None, 'ALL')
        if status == 'OK':
            uid_list = uid_data[0].split() if uid_data[0] else []
            print(f"   Total UIDs: {len(uid_list)}")
            print(f"   Already processed: {len(processed_uids)} emails")

            # Filter to only unprocessed UIDs before fetching full messages
            unprocessed_uids = [uid for uid in uid_list if uid.decode() not in processed_uids]
            diagnostics['unprocessed_checked'] = len(unprocessed_uids)
            print(f"   Unprocessed: {len(unprocessed_uids)} emails to check")

            # Process in reverse order (newest first) for better UX
            for uid in reversed(unprocessed_uids):
                status, msg_data = mail.uid('fetch', uid, '(RFC822)')
                if status == 'OK':
                    msg = email.message_from_bytes(msg_data[0][1])
                    msg_uid = uid.decode()

                    # Check if email has attachments (handles forwarded emails with nested attachments)
                    has_attachments = False
                    attachment_count = 0

                    for part in msg.walk():
                        # Direct attachments
                        if part.get_content_disposition() == 'attachment':
                            has_attachments = True
                            filename = part.get_filename()
                            if filename:
                                attachment_count += 1
                                print(f"    Found attachment: {filename}")

                        # Application types (PDFs, etc.)
                        elif part.get_content_maintype() == 'application':
                            has_attachments = True
                            filename = part.get_filename()
                            if filename:
                                attachment_count += 1
                                print(f"    Found application: {filename}")

                        # Forwarded emails (message/rfc822) - check their attachments
                        elif part.get_content_type() == 'message/rfc822':
                            print(f"    Found forwarded message - checking nested attachments...")
                            try:
                                payload = part.get_payload()
                                if isinstance(payload, list):
                                    forwarded_msg = payload[0] if payload else None
                                else:
                                    forwarded_msg = payload

                                if forwarded_msg:
                                    if hasattr(forwarded_msg, 'walk'):
                                        for fwd_part in forwarded_msg.walk():
                                            if fwd_part.get_content_disposition() == 'attachment' or fwd_part.get_content_maintype() == 'application':
                                                has_attachments = True
                                                fwd_filename = fwd_part.get_filename()
                                                if fwd_filename:
                                                    attachment_count += 1
                                                    print(f"    Found nested attachment: {fwd_filename}")
                            except Exception as e:
                                print(f"    (Could not parse nested message: {e})")

                    if has_attachments:
                        emails.append((msg_uid, msg))
                        diagnostics['with_attachments'] += 1
                        subject = msg.get('Subject', 'No Subject')
                        print(f"  ✓ Found new email with {attachment_count} attachment(s): {subject}")
                    else:
                        diagnostics['without_attachments'] += 1
                        subject = msg.get('Subject', 'No Subject')
                        print(f"  ⊘ Skipped (no attachments): {subject[:60]}")

        mail.close()
        mail.logout()
        print(f"✓ IMAP disconnected - {len(emails)} new emails with attachments")
        return {'emails': emails, 'diagnostics': diagnostics}

    except imaplib.IMAP4.error as e:
        error_msg = str(e)
        print(f"✗ IMAP Error: {error_msg}")

        if "BasicAuthBlocked" in error_msg or "LogonDenied" in error_msg:
            diagnostics['error'] = 'Outlook blocked basic auth. Use an App Password instead of your regular password.'
        elif "LOGIN failed" in error_msg or "AUTHENTICATIONFAILED" in error_msg:
            diagnostics['error'] = f'Login failed for {PO_EMAIL_ADDRESS}. Check email address and app password are correct.'
        else:
            diagnostics['error'] = f'IMAP error: {error_msg}'

        import traceback
        traceback.print_exc()
        return {'emails': [], 'diagnostics': diagnostics}

    except Exception as e:
        diagnostics['error'] = f'Connection error: {str(e)}'
        print(f"✗ IMAP error: {e}")
        import traceback
        traceback.print_exc()
        return {'emails': [], 'diagnostics': diagnostics}

def extract_attachments_from_email(msg):
    """
    Extract attachments from an email message
    Returns list of (filename, file_content) tuples
    """
    attachments = []
    try:
        for part in msg.walk():
            if part.get_content_disposition() == 'attachment':
                filename = part.get_filename()
                if filename:
                    # Decode filename if needed
                    if isinstance(filename, str):
                        # Handle encoded-word format
                        try:
                            decoded_parts = decode_header(filename)
                            filename = ''.join([part.decode(enc or 'utf-8') if isinstance(part, bytes) else part
                                               for part, enc in decoded_parts])
                        except:
                            pass

                    file_content = part.get_payload(decode=True)
                    attachments.append((filename, file_content))
                    print(f"  📎 Extracted attachment: {filename}")

        return attachments
    except Exception as e:
        print(f"✗ Error extracting attachments: {e}")
        return []

def process_email_attachments(msg_uid, msg, attachments):
    """
    Process email attachments and match with POs
    Returns results dictionary
    """
    results = {
        'success': True,
        'email_uid': msg_uid,
        'email_sender': msg.get('From', 'Unknown'),
        'email_subject': msg.get('Subject', 'No Subject'),
        'email_date': msg.get('Date', ''),
        'attachments_processed': 0,
        'matched': 0,
        'unmatched': [],
        'errors': [],
        'details': []
    }

    try:
        # Get PO map for matching
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute("""SELECT id, tech_name, job_name, estimated_cost, client_name
                     FROM po_requests
                     WHERE (status='awaiting_invoice' OR status='approved')
                     AND (invoice_filename IS NULL OR invoice_filename = '')""")
        po_map = {}
        for row in c.fetchall():
            po_map[row[0]] = {
                'id': row[0],
                'tech_name': row[1],
                'job_name': row[2],
                'estimated_cost': row[3],
                'client_name': row[4]
            }
        conn.close()

        print(f"  Found {len(po_map)} POs awaiting invoices")

        # Process each attachment
        for filename, file_content in attachments:
            results['attachments_processed'] += 1

            # Only process PDF files
            if not filename.lower().endswith('.pdf'):
                results['unmatched'].append({
                    'filename': filename,
                    'reason': 'Not a PDF file'
                })
                continue

            # Save temporary file
            temp_path = os.path.join(app.config['BULK_UPLOAD_FOLDER'], f'email_{msg_uid}_{filename}')
            try:
                with open(temp_path, 'wb') as f:
                    f.write(file_content)

                # Process with bulk PDF processor
                timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
                pdf_results = process_bulk_pdf(temp_path, timestamp)

                results['matched'] += pdf_results.get('matched', 0)
                results['details'].append({
                    'filename': filename,
                    'results': pdf_results
                })

                # Clean up temp file
                try:
                    os.remove(temp_path)
                except:
                    pass

            except Exception as e:
                results['errors'].append({
                    'filename': filename,
                    'error': str(e)
                })
                print(f"    ✗ Error processing {filename}: {e}")

        return results

    except Exception as e:
        print(f"✗ Error processing email attachments: {e}")
        results['success'] = False
        results['errors'].append(str(e))
        return results

def create_invoice_notification(invoice_number, invoice_cost, invoice_filename, email_sender, email_subject, email_date, text_preview):
    """Create a notification for unmatched invoice and send email alert"""
    try:
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()

        created_at = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        c.execute("""INSERT INTO invoice_notifications
                     (invoice_number, invoice_cost, invoice_filename, email_sender, email_subject,
                      email_received_date, text_preview, status, created_at)
                     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                 (invoice_number, invoice_cost, invoice_filename, email_sender, email_subject,
                  email_date, text_preview, 'pending', created_at))
        conn.commit()
        conn.close()

        # Send email notification
        send_notification_email(invoice_number, invoice_cost, email_sender, email_subject, invoice_filename, text_preview)
        print(f"✓ Created notification for unmatched invoice {invoice_number}")
        return True
    except Exception as e:
        print(f"✗ Error creating invoice notification: {e}")
        return False

def log_email_processing(email_uid, email_sender, email_subject, email_date, attachments_count, results):
    """Log email processing to database and create notifications for unmatched invoices"""
    try:
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()

        c.execute("""INSERT INTO email_processing_log
                     (email_uid, email_sender, email_subject, email_date, attachments_processed, processed_at, results)
                     VALUES (?, ?, ?, ?, ?, ?, ?)""",
                 (email_uid, email_sender, email_subject, email_date, attachments_count,
                  datetime.now().strftime('%Y-%m-%d %H:%M:%S'), json.dumps(results)))
        conn.commit()

        # Create notifications for unmatched invoices
        if results.get('errors'):
            for error in results['errors']:
                if error.get('error') == 'NO MATCHING PO FOUND':
                    create_invoice_notification(
                        invoice_number=error.get('invoice_number', 'Unknown'),
                        invoice_cost=error.get('cost', 0),
                        invoice_filename=error.get('filename', 'Unknown'),
                        email_sender=email_sender,
                        email_subject=email_subject,
                        email_date=email_date,
                        text_preview=error.get('text_preview', '')
                    )

        conn.close()
        print(f"✓ Logged email processing: {email_sender}")
    except Exception as e:
        print(f"✗ Error logging email: {e}")

def auto_check_po_emails():
    """Background task: Automatically check PO emails every hour"""
    if not PO_EMAIL_MONITORING_ENABLED:
        return

    try:
        print(f"\n{'='*60}")
        print(f"📧 AUTO EMAIL CHECK - {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
        print(f"   Checking: {PO_EMAIL_ADDRESS}")
        print(f"   Provider: {PO_EMAIL_PROVIDER}")
        print(f"{'='*60}")

        # Fetch emails (Graph API first, then IMAP fallback)
        result = fetch_emails()
        emails = result.get('emails', [])
        diag = result.get('diagnostics', {})
        source = diag.get('source', 'imap')

        if diag.get('error'):
            print(f"✗ Email fetch error: {diag['error']}")
            return

        if not emails:
            print(f"✓ No new emails with attachments found")
            return

        # Process each email
        processed_count = 0
        matched_count = 0

        for msg_uid, msg in emails:
            # Extract attachments based on source
            if source == 'graph_api':
                attachments = extract_attachments_from_graph_message(msg_uid)
            else:
                attachments = extract_attachments_from_email(msg)
            if not attachments:
                continue

            processed_count += 1

            # Process attachments
            email_results = process_email_attachments(msg_uid, msg, attachments)
            matched_count += email_results.get('matched', 0)

            # Log to database
            log_email_processing(
                msg_uid,
                email_results.get('email_sender', 'Unknown'),
                email_results.get('email_subject', 'No Subject'),
                email_results.get('email_date', ''),
                email_results.get('attachments_processed', 0),
                email_results
            )

        print(f"\n{'='*60}")
        print(f"✅ AUTO EMAIL CHECK COMPLETE")
        print(f"  Emails processed: {processed_count}")
        print(f"  Matched invoices: {matched_count}")
        print(f"{'='*60}\n")

    except Exception as e:
        print(f"✗ Auto email check error: {e}")
        import traceback
        traceback.print_exc()

