@app.route('/match_notification_to_po', methods=['POST'])
def match_notification_to_po():
    """Manually match an unmatched invoice notification to a PO"""
    if 'username' not in session or session['role'] != 'office':
        return jsonify({'success': False, 'error': 'Unauthorized'})

    try:
        data = request.get_json()
        notification_id = data.get('notification_id')
        po_id = data.get('po_id')

        if not notification_id or not po_id:
            return jsonify({'success': False, 'error': 'Missing notification_id or po_id'})

        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()

        # Get notification details
        c.execute("""SELECT invoice_number, invoice_cost, invoice_filename, text_preview
                     FROM invoice_notifications
                     WHERE id=?""", (notification_id,))
        notification = c.fetchone()

        if not notification:
            conn.close()
            return jsonify({'success': False, 'error': 'Notification not found'})

        # Get PO details
        c.execute("SELECT id, status FROM po_requests WHERE id=?", (po_id,))
        po = c.fetchone()

        if not po:
            conn.close()
            return jsonify({'success': False, 'error': 'PO not found'})

        invoice_number = notification[0]
        invoice_cost = notification[1]
        invoice_filename = notification[2]

        # Check for duplicate invoice number on this PO before inserting
        existing = c.execute("""SELECT id FROM invoices WHERE po_id=? AND invoice_number=?""",
                             (po_id, invoice_number)).fetchone()
        if existing:
            conn.close()
            return jsonify({'success': False, 'error': f'Invoice {invoice_number} has already been matched to this PO'})

        # Create invoice record
        c.execute("""INSERT INTO invoices (po_id, invoice_number, invoice_cost, invoice_filename, invoice_date, invoice_upload_date, created_at)
                     VALUES (?, ?, ?, ?, ?, ?, ?)""",
                 (po_id, invoice_number, invoice_cost, invoice_filename, 'N/A',
                  datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                  datetime.now().strftime('%Y-%m-%d %H:%M:%S')))

        # Update notification status
        matched_at = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        c.execute("""UPDATE invoice_notifications
                     SET status='matched', matched_po_id=?, matched_at=?
                     WHERE id=?""", (po_id, matched_at, notification_id))

        # Update PO status to matched
        c.execute("UPDATE po_requests SET status=? WHERE id=?", ('matched', po_id))

        conn.commit()
        conn.close()

        log_activity(session['username'], 'match_notification', 'notification', notification_id,
                    f"Matched notification {notification_id} to PO {po_id}")

        return jsonify({'success': True, 'message': f'Matched invoice {invoice_number} to PO {po_id}'})

    except Exception as e:
        return jsonify({'success': False, 'error': f'Server error: {str(e)}'})

@app.route('/delete_po', methods=['POST'])
def delete_po():
    """Delete an active PO (office only)"""
    if 'username' not in session or session['role'] != 'office':
        return jsonify({'success': False, 'error': 'Unauthorized'})

    try:
        data = request.get_json()
        po_id = data.get('po_id')

        if not po_id:
            return jsonify({'success': False, 'error': 'No PO ID provided'})

        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()

        # Get PO details
        c.execute("SELECT status, invoice_filename FROM po_requests WHERE id=?", (po_id,))
        po = c.fetchone()

        if not po:
            conn.close()
            return jsonify({'success': False, 'error': 'PO not found'})

        # Only allow deletion of active POs (approved or awaiting_invoice)
        status = po[0]
        if status not in ('approved', 'awaiting_invoice'):
            conn.close()
            return jsonify({'success': False, 'error': f'Cannot delete PO with status: {status}'})

        # Delete associated invoice file if exists
        invoice_filename = po[1]
        if invoice_filename and invoice_filename != 'MANUAL_ENTRY':
            invoice_path = os.path.join(app.config['UPLOAD_FOLDER'], invoice_filename)
            if os.path.exists(invoice_path):
                try:
                    os.remove(invoice_path)
                except Exception as e:
                    print(f"WARNING: Could not delete invoice file: {e}")

        # Delete the PO request
        c.execute("DELETE FROM po_requests WHERE id=?", (po_id,))
        conn.commit()
        conn.close()

        return jsonify({'success': True, 'message': 'PO deleted successfully'})

    except Exception as e:
        print(f"ERROR in delete_po: {str(e)}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': f'Server error: {str(e)}'})

@app.route('/undo_invoice_match', methods=['POST'])
def undo_invoice_match():
    """Undo an invoice match - resets PO back to awaiting_invoice for re-matching"""
    if 'username' not in session or session['role'] != 'office':
        return jsonify({'success': False, 'error': 'Unauthorized'})

    data = request.get_json()
    po_id = data.get('po_id')
    invoice_id = data.get('invoice_id')

    if not po_id:
        return jsonify({'success': False, 'error': 'Missing po_id'})

    try:
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()

        # Delete the specific invoice record if provided
        if invoice_id:
            c.execute("DELETE FROM invoices WHERE id=? AND po_id=?", (invoice_id, po_id))
            print(f"✓ Deleted invoice record {invoice_id} for PO {po_id}")

        # Check if there are remaining invoices for this PO
        c.execute("SELECT COUNT(*) FROM invoices WHERE po_id=?", (po_id,))
        remaining = c.fetchone()[0]

        if remaining == 0:
            # No more invoices - reset PO back to awaiting_invoice
            c.execute("""UPDATE po_requests
                         SET status='awaiting_invoice',
                             invoice_filename=NULL, invoice_number=NULL,
                             invoice_cost=NULL, match_method=NULL,
                             invoice_date=NULL, invoice_upload_date=NULL
                         WHERE id=?""", (po_id,))
            print(f"✓ Reset PO {po_id} back to awaiting_invoice (no remaining invoices)")

            # Also clear the email processing log entries that matched this PO
            # so the system will re-process those emails
            c.execute("DELETE FROM email_processing_log WHERE results LIKE ?",
                      (f'%"po_number": {po_id}%',))
        else:
            # Still has other invoices - update PO cost from remaining invoices
            c.execute("SELECT SUM(CAST(invoice_cost AS REAL)) FROM invoices WHERE po_id=?", (po_id,))
            total_cost = c.fetchone()[0] or 0
            c.execute("UPDATE po_requests SET invoice_cost=? WHERE id=?", (total_cost, po_id))
            print(f"✓ Removed one invoice from PO {po_id}, {remaining} remaining, updated cost to ${total_cost:.2f}")

        conn.commit()
        conn.close()

        return jsonify({
            'success': True,
            'message': f'Invoice match undone for PO {po_id}',
            'remaining_invoices': remaining
        })

    except Exception as e:
        print(f"✗ Error undoing invoice match: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)})


