@app.route('/community_billing_tech')
def community_billing_tech():
    """Tech side - select community and date, show past submissions and drafts"""
    if 'username' not in session or session.get('role') != 'technician':
        return redirect(url_for('login'))

    # Get list of communities from communities table
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("SELECT name FROM communities WHERE active = 1 ORDER BY name")
    communities = [row[0] for row in c.fetchall()]

    # Get tech's submissions for the current month
    username = session.get('username')
    current_month = datetime.now().strftime('%Y-%m')
    c.execute("""SELECT id, community_name, work_date, status, submitted_at, created_at
                 FROM community_billing_submissions
                 WHERE tech_username = ? AND work_date LIKE ?
                 ORDER BY work_date DESC, COALESCE(submitted_at, created_at) DESC""",
             (username, current_month + '%'))

    submissions = []
    for row in c.fetchall():
        submission_id = row[0]

        # Find which clocks have actual data entered by the tech
        c.execute("""SELECT DISTINCT zone_and_address
                     FROM community_billing_line_items
                     WHERE submission_id = ?
                       AND (COALESCE(nozzle,0) + COALESCE(pop_up_6_inch,0) +
                            COALESCE(pop_up_12_inch,0) + COALESCE(rotor_6_inch,0) +
                            COALESCE(new_pop_up_6_inch,0) + COALESCE(new_pop_up_12_inch,0) +
                            COALESCE(riser,0) + COALESCE(solenoid,0) +
                            COALESCE(stat_decoder_1,0) > 0
                            OR (notes IS NOT NULL AND TRIM(notes) != ''))""",
                 (submission_id,))
        clock_nums = set()
        for (zone,) in c.fetchall():
            if zone:
                m = re.match(r'^Clock\s+(\d+)', zone, re.IGNORECASE)
                if m:
                    clock_nums.add(int(m.group(1)))

        clocks_label = ', '.join(f'Clock {n}' for n in sorted(clock_nums)) if clock_nums else ''

        submissions.append({
            'id': submission_id,
            'community': row[1],
            'work_date': (row[2] or '').strip(),
            'status': row[3],
            'submitted_at': row[4],
            'created_at': row[5],
            'clocks_label': clocks_label
        })

    conn.close()

    return render_template_string(COMMUNITY_BILLING_TECH_TEMPLATE,
                                 username=username,
                                 communities=communities,
                                 submissions=submissions,
                                 user_lang=session.get('user_lang', 'en'))

@app.route('/community_billing_spreadsheet', methods=['POST', 'GET'])
def community_billing_spreadsheet():
    """Tech side - view and edit spreadsheet"""
    if 'username' not in session or session.get('role') != 'technician':
        if request.method == 'POST':
            return jsonify({'success': False, 'error': 'Access denied', 'redirect': '/login'}), 401
        return redirect(url_for('login'))

    # Handle both POST (JSON) and GET (query params)
    if request.method == 'POST':
        data = request.get_json()
        community = data.get('community')
        work_date = data.get('work_date')
    else:
        community = request.args.get('community')
        work_date = request.args.get('work_date')

    if not community or not work_date:
        return jsonify({'success': False, 'error': 'Missing community or date'})

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    # Get or create submission
    if request.method == 'POST':
        # POST = tech clicked "Next" to start a new submission — always create a fresh draft
        c.execute("""INSERT INTO community_billing_submissions
                     (community_name, tech_username, work_date, created_at)
                     VALUES (?, ?, ?, ?)""",
                 (community, session.get('username'), work_date, datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
        submission_id = c.lastrowid
        conn.commit()
        conn.close()
        return jsonify({'success': True, 'submission_id': submission_id})
    else:
        # GET = loading an existing submission (from list or direct URL)
        submission_id_param = request.args.get('submission_id')
        if submission_id_param:
            submission_id = int(submission_id_param)
        else:
            # Fallback: find the most recent draft for this combo, or create one
            c.execute("""SELECT id FROM community_billing_submissions
                         WHERE community_name = ? AND tech_username = ? AND work_date = ?
                         AND status = 'draft'
                         ORDER BY id DESC LIMIT 1""",
                     (community, session.get('username'), work_date))
            submission = c.fetchone()
            if submission:
                submission_id = submission[0]
            else:
                c.execute("""INSERT INTO community_billing_submissions
                             (community_name, tech_username, work_date, created_at)
                             VALUES (?, ?, ?, ?)""",
                         (community, session.get('username'), work_date, datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
                submission_id = c.lastrowid
                conn.commit()

    # Get all line items for this submission
    c.execute("""SELECT id, zone_and_address, nozzle, pop_up_6_inch, pop_up_12_inch,
                        rotor_6_inch, new_pop_up_6_inch, new_pop_up_12_inch,
                        riser, solenoid, stat_decoder_1, notes
                 FROM community_billing_line_items
                 WHERE submission_id = ?
                 ORDER BY id""", (submission_id,))

    line_items = []
    for row in c.fetchall():
        line_items.append({
            'id': row[0],
            'zone_and_address': row[1],
            'nozzle': row[2],
            'pop_up_6_inch': row[3],
            'pop_up_12_inch': row[4],
            'rotor_6_inch': row[5],
            'new_pop_up_6_inch': row[6],
            'new_pop_up_12_inch': row[7],
            'riser': row[8],
            'solenoid': row[9],
            'stat_decoder_1': row[10],
            'notes': row[11]
        })

    # If no line items yet, populate from house numbers or clock addresses added by office user
    if not line_items:
        # Get community ID first
        c.execute("SELECT id, COALESCE(num_clocks, 0) FROM communities WHERE name = ? AND active = 1", (community,))
        community_row = c.fetchone()
        if community_row:
            community_id = community_row[0]
            comm_num_clocks = community_row[1]

            if comm_num_clocks == 0:
                c.execute("SELECT COUNT(*) FROM verona_walk_clock_addresses WHERE community_id = ?", (community_id,))
                comm_uses_clocks = c.fetchone()[0] > 0
            else:
                comm_uses_clocks = True

            if comm_uses_clocks:
                # Clock-based community: get all clock addresses
                c.execute("""SELECT clock_number, address, COALESCE(is_common_area, 0) FROM verona_walk_clock_addresses
                             WHERE community_id = ?
                             ORDER BY clock_number, id""", (community_id,))
                addresses = c.fetchall()

                # Create a line item for each address
                for clock_num, address, is_ca in addresses:
                    if is_ca:
                        label = f"Clock {clock_num} Common Area - {address}"
                    else:
                        label = f"Clock {clock_num} - {address}"

                    c.execute("""INSERT INTO community_billing_line_items
                                 (submission_id, zone_and_address, created_at)
                                 VALUES (?, ?, ?)""",
                             (submission_id, label, datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
            else:
                # Standard community: get all house numbers
                c.execute("SELECT house_number FROM community_house_numbers WHERE community_id = ? ORDER BY house_number",
                         (community_id,))
                house_numbers = [row[0] for row in c.fetchall()]

                # Create a line item for each house number
                for house_number in house_numbers:
                    c.execute("""INSERT INTO community_billing_line_items
                                 (submission_id, zone_and_address, created_at)
                                 VALUES (?, ?, ?)""",
                             (submission_id, house_number, datetime.now().strftime('%Y-%m-%d %H:%M:%S')))

            conn.commit()

            # Re-fetch the newly created line items
            c.execute("""SELECT id, zone_and_address, nozzle, pop_up_6_inch, pop_up_12_inch,
                                rotor_6_inch, new_pop_up_6_inch, new_pop_up_12_inch,
                                riser, solenoid, stat_decoder_1
                         FROM community_billing_line_items
                         WHERE submission_id = ?
                         ORDER BY id""", (submission_id,))
            for row in c.fetchall():
                line_items.append({
                    'id': row[0],
                    'zone_and_address': row[1],
                    'nozzle': row[2],
                    'pop_up_6_inch': row[3],
                    'pop_up_12_inch': row[4],
                    'rotor_6_inch': row[5],
                    'new_pop_up_6_inch': row[6],
                    'new_pop_up_12_inch': row[7],
                    'riser': row[8],
                    'solenoid': row[9],
                    'stat_decoder_1': row[10]
                })

    # Get submission status
    c.execute("SELECT status, submitted_at FROM community_billing_submissions WHERE id = ?", (submission_id,))
    submission_info = c.fetchone()
    status = submission_info[0] if submission_info else 'draft'

    # Get community ID and num_clocks (must be active)
    c.execute("SELECT id, COALESCE(num_clocks, 0) FROM communities WHERE name = ? AND active = 1", (community,))
    community_row = c.fetchone()
    community_id = community_row[0] if community_row else None
    num_clocks = community_row[1] if community_row else 0

    # If num_clocks is not configured, check for existing clock addresses (e.g. Verona Walk HOA)
    if community_id and num_clocks == 0:
        c.execute("SELECT MAX(clock_number) FROM verona_walk_clock_addresses WHERE community_id = ?", (community_id,))
        max_clock = c.fetchone()[0] or 0
        num_clocks = max_clock

    # Sync draft line items with current community addresses on every page load.
    # This catches any address changes the office made since the draft was created.
    if community_id and status == 'draft':
        sync_community_drafts(c, community, community_id)
        conn.commit()

        # Re-fetch line items so the page renders the up-to-date labels
        c.execute("""SELECT id, zone_and_address, nozzle, pop_up_6_inch, pop_up_12_inch,
                            rotor_6_inch, new_pop_up_6_inch, new_pop_up_12_inch,
                            riser, solenoid, stat_decoder_1, notes
                     FROM community_billing_line_items
                     WHERE submission_id = ?
                     ORDER BY id""", (submission_id,))
        line_items = []
        for row in c.fetchall():
            line_items.append({
                'id': row[0],
                'zone_and_address': row[1],
                'nozzle': row[2],
                'pop_up_6_inch': row[3],
                'pop_up_12_inch': row[4],
                'rotor_6_inch': row[5],
                'new_pop_up_6_inch': row[6],
                'new_pop_up_12_inch': row[7],
                'riser': row[8],
                'solenoid': row[9],
                'stat_decoder_1': row[10],
                'notes': row[11]
            })

    conn.close()

    is_verona_walk = (num_clocks > 0)

    return render_template_string(COMMUNITY_BILLING_SPREADSHEET_TEMPLATE,
                                 submission_id=submission_id,
                                 community=community,
                                 community_id=community_id,
                                 work_date=work_date,
                                 line_items=line_items,
                                 status=status,
                                 num_clocks=num_clocks,
                                 is_verona_walk=is_verona_walk,
                                 user_lang=session.get('user_lang', 'en'))

@app.route('/community_billing_save_item', methods=['POST'])
def community_billing_save_item():
    """Save or update a line item"""
    if 'username' not in session or session.get('role') != 'technician':
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    data = request.get_json()
    submission_id = data.get('submission_id')
    item_id = data.get('item_id')
    zone_and_address = data.get('zone_and_address')

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    try:
        photos_val = data.get('photos')
        if isinstance(photos_val, list):
            import json as _json
            photos_val = _json.dumps(photos_val)
        photos_val = photos_val or '[]'

        if item_id:
            # Update existing item
            c.execute("""UPDATE community_billing_line_items
                         SET zone_and_address = ?, nozzle = ?, pop_up_6_inch = ?,
                             pop_up_12_inch = ?, rotor_6_inch = ?, new_pop_up_6_inch = ?,
                             new_pop_up_12_inch = ?, riser = ?, solenoid = ?, stat_decoder_1 = ?, notes = ?, photos = ?
                         WHERE id = ? AND submission_id = ?""",
                     (zone_and_address,
                      int(data.get('nozzle') or 0),
                      int(data.get('pop_up_6_inch') or 0),
                      int(data.get('pop_up_12_inch') or 0),
                      int(data.get('rotor_6_inch') or 0),
                      int(data.get('new_pop_up_6_inch') or 0),
                      int(data.get('new_pop_up_12_inch') or 0),
                      int(data.get('riser') or 0),
                      int(data.get('solenoid') or 0),
                      int(data.get('stat_decoder_1') or 0),
                      data.get('notes') or '',
                      photos_val,
                      item_id, submission_id))
        else:
            # Create new item
            c.execute("""INSERT INTO community_billing_line_items
                         (submission_id, zone_and_address, nozzle, pop_up_6_inch,
                          pop_up_12_inch, rotor_6_inch, new_pop_up_6_inch,
                          new_pop_up_12_inch, riser, solenoid, stat_decoder_1, notes, photos, created_at)
                         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                     (submission_id, zone_and_address,
                      int(data.get('nozzle') or 0),
                      int(data.get('pop_up_6_inch') or 0),
                      int(data.get('pop_up_12_inch') or 0),
                      int(data.get('rotor_6_inch') or 0),
                      int(data.get('new_pop_up_6_inch') or 0),
                      int(data.get('new_pop_up_12_inch') or 0),
                      int(data.get('riser') or 0),
                      int(data.get('solenoid') or 0),
                      int(data.get('stat_decoder_1') or 0),
                      data.get('notes') or '',
                      photos_val,
                      datetime.now().strftime('%Y-%m-%d %H:%M:%S')))

        conn.commit()
        new_item_id = c.lastrowid if not item_id else item_id
        conn.close()

        return jsonify({'success': True, 'item_id': new_item_id})
    except Exception as e:
        conn.close()
        return jsonify({'success': False, 'error': str(e)})

@app.route('/community_billing_save_draft', methods=['POST'])
def community_billing_save_draft():
    """Save entire draft - all line items at once"""
    if 'username' not in session or session.get('role') != 'technician':
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    try:
        data = request.get_json()
        if not data:
            return jsonify({'success': False, 'error': 'No data provided'})

        submission_id = data.get('submission_id')
        line_items = data.get('line_items', [])

        print(f"\n=== SAVE DRAFT ===")
        print(f"Submission ID: {submission_id}")
        print(f"Items to save: {len(line_items)}")

        if not submission_id:
            return jsonify({'success': False, 'error': 'Missing submission_id'})

        if not line_items:
            return jsonify({'success': False, 'error': 'No line items provided'})

        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()

        # Get existing item IDs
        c.execute("SELECT id FROM community_billing_line_items WHERE submission_id = ?",
                 (submission_id,))
        existing_ids = {row[0] for row in c.fetchall()}
        print(f"Existing item IDs in DB: {existing_ids}")

        # Helper function to convert to int
        def safe_int(val):
            if not val or val == '':
                return 0
            try:
                return int(float(val))
            except (ValueError, TypeError):
                return 0

        # Process each line item
        updated_count = 0
        inserted_count = 0
        for idx, item in enumerate(line_items):
            item_id_raw = item.get('id')
            if not item_id_raw:
                print(f"Item {idx}: No ID, skipping")
                continue

            # Convert item_id to int for comparison
            try:
                item_id = int(item_id_raw)
            except (ValueError, TypeError):
                print(f"Item {idx}: Invalid ID {item_id_raw}, skipping")
                continue

            zone_and_address = (item.get('zone_and_address') or '').strip()
            nozzle = safe_int(item.get('nozzle'))
            pop_up_6_inch = safe_int(item.get('pop_up_6_inch'))
            pop_up_12_inch = safe_int(item.get('pop_up_12_inch'))
            rotor_6_inch = safe_int(item.get('rotor_6_inch'))
            new_pop_up_6_inch = safe_int(item.get('new_pop_up_6_inch'))
            new_pop_up_12_inch = safe_int(item.get('new_pop_up_12_inch'))
            riser = safe_int(item.get('riser'))
            solenoid = safe_int(item.get('solenoid'))
            stat_decoder_1 = safe_int(item.get('stat_decoder_1'))
            notes = (item.get('notes') or '').strip()
            photos_raw = item.get('photos')
            if isinstance(photos_raw, list):
                import json as _json
                photos_str = _json.dumps(photos_raw)
            else:
                photos_str = photos_raw or '[]'

            print(f"Item {idx} (ID={item_id}): nozzle={nozzle}, pop_up_6={pop_up_6_inch}, pop_up_12={pop_up_12_inch}")

            if item_id in existing_ids:
                # Update existing item
                print(f"  -> UPDATING item {item_id}")
                c.execute("""UPDATE community_billing_line_items
                             SET zone_and_address = ?, nozzle = ?, pop_up_6_inch = ?,
                                 pop_up_12_inch = ?, rotor_6_inch = ?, new_pop_up_6_inch = ?,
                                 new_pop_up_12_inch = ?, riser = ?, solenoid = ?, stat_decoder_1 = ?, notes = ?, photos = ?
                             WHERE id = ? AND submission_id = ?""",
                         (zone_and_address, nozzle, pop_up_6_inch, pop_up_12_inch,
                          rotor_6_inch, new_pop_up_6_inch, new_pop_up_12_inch,
                          riser, solenoid, stat_decoder_1, notes, photos_str, item_id, submission_id))
                updated_count += 1
            else:
                # Insert new item
                print(f"  -> INSERTING new item {item_id}")
                c.execute("""INSERT INTO community_billing_line_items
                             (submission_id, zone_and_address, nozzle, pop_up_6_inch,
                              pop_up_12_inch, rotor_6_inch, new_pop_up_6_inch,
                              new_pop_up_12_inch, riser, solenoid, stat_decoder_1, notes, photos, created_at)
                             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                         (submission_id, zone_and_address, nozzle, pop_up_6_inch,
                          pop_up_12_inch, rotor_6_inch, new_pop_up_6_inch,
                          new_pop_up_12_inch, riser, solenoid, stat_decoder_1, notes, photos_str,
                          datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
                inserted_count += 1

        conn.commit()

        # Verify the save by querying back
        c.execute("SELECT id, nozzle, pop_up_6_inch FROM community_billing_line_items WHERE submission_id = ?",
                 (submission_id,))
        verified = c.fetchall()
        print(f"\nVERIFICATION: {len(verified)} items in DB after save")
        for v in verified:
            print(f"  ID {v[0]}: nozzle={v[1]}, pop_up_6={v[2]}")

        conn.close()
        print(f"Save complete: {updated_count} updated, {inserted_count} inserted\n")
        return jsonify({'success': True, 'message': f'Saved {updated_count + inserted_count} items'})

    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': f'Error: {str(e)}'})

@app.route('/community_billing_upload_photo', methods=['POST'])
def community_billing_upload_photo():
    """Upload a photo attached to a community billing line item"""
    if 'username' not in session or session.get('role') != 'technician':
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    if 'photo' not in request.files:
        return jsonify({'success': False, 'error': 'No photo provided'})

    photo = request.files['photo']
    if not photo or photo.filename == '':
        return jsonify({'success': False, 'error': 'Empty file'})

    allowed_extensions = {'.jpg', '.jpeg', '.png', '.gif', '.webp', '.heic', '.heif'}
    ext = os.path.splitext(photo.filename or '')[1].lower()
    if ext not in allowed_extensions:
        return jsonify({'success': False, 'error': 'Invalid file type'})

    timestamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    safe_user = ''.join(c for c in session.get('username', 'user') if c.isalnum() or c in ('_', '-'))
    filename = f"cbp_{safe_user}_{timestamp}{ext}"
    save_path = os.path.join(app.config['COMMUNITY_PHOTO_FOLDER'], filename)
    photo.save(save_path)

    return jsonify({'success': True, 'filename': filename})

@app.route('/community_billing_photo/<filename>')
def community_billing_photo(filename):
    """Serve a community billing photo"""
    if 'username' not in session:
        return 'Unauthorized', 401
    # Sanitize: only allow safe filenames (no path traversal)
    if '..' in filename or '/' in filename or '\\' in filename:
        return 'Invalid filename', 400
    return send_from_directory(app.config['COMMUNITY_PHOTO_FOLDER'], filename)

