@app.route('/community_billing_reopen', methods=['POST'])
def community_billing_reopen():
    """Reopen a finalized submission for editing"""
    if 'username' not in session or session.get('role') != 'technician':
        return jsonify({'success': False, 'error': 'Access denied'})

    data = request.get_json()
    submission_id = data.get('submission_id')

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    try:
        c.execute("""SELECT status FROM community_billing_submissions
                     WHERE id = ? AND tech_username = ?""",
                 (submission_id, session.get('username')))
        result = c.fetchone()

        if not result:
            conn.close()
            return jsonify({'success': False, 'error': 'Submission not found'})

        if result[0] != 'submitted':
            conn.close()
            return jsonify({'success': False, 'error': 'Submission is not finalized'})

        c.execute("""UPDATE community_billing_submissions
                     SET status = 'draft', submitted_at = NULL
                     WHERE id = ? AND tech_username = ?""",
                 (submission_id, session.get('username')))
        conn.commit()
        conn.close()
        return jsonify({'success': True})
    except Exception as e:
        conn.close()
        return jsonify({'success': False, 'error': str(e)})

@app.route('/community_billing_delete_draft', methods=['POST'])
def community_billing_delete_draft():
    """Delete a draft submission"""
    if 'username' not in session or session.get('role') != 'technician':
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    data = request.get_json()
    submission_id = data.get('submission_id')

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    try:
        # Verify the submission belongs to the current user and is a draft
        c.execute("""SELECT status FROM community_billing_submissions
                     WHERE id = ? AND tech_username = ?""",
                 (submission_id, session.get('username')))
        result = c.fetchone()

        if not result:
            conn.close()
            return jsonify({'success': False, 'error': 'Submission not found'})

        if result[0] == 'submitted':
            conn.close()
            return jsonify({'success': False, 'error': 'Cannot delete submitted submissions'})

        # Delete the submission and its line items (CASCADE handles line items)
        c.execute("DELETE FROM community_billing_submissions WHERE id = ?", (submission_id,))

        conn.commit()
        conn.close()
        return jsonify({'success': True})
    except Exception as e:
        conn.close()
        return jsonify({'success': False, 'error': str(e)})

@app.route('/manage_communities', methods=['GET', 'POST'])
def manage_communities():
    """Office user management page for communities"""
    if 'username' not in session or session.get('role') != 'office':
        return redirect(url_for('login'))

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    if request.method == 'POST':
        action = request.form.get('action')

        if action == 'add':
            community_name = request.form.get('community_name', '').strip()
            if not community_name:
                flash('Community name is required', 'error')
            else:
                try:
                    c.execute("INSERT INTO communities (name, created_by, created_at) VALUES (?, ?, ?)",
                             (community_name, session.get('username'), datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
                    conn.commit()
                    flash(f'Community "{community_name}" added successfully', 'success')
                except sqlite3.IntegrityError:
                    flash(f'Community "{community_name}" already exists', 'error')

        elif action == 'delete':
            community_id = request.form.get('community_id')
            try:
                # Get community name first
                c.execute("SELECT name FROM communities WHERE id = ?", (community_id,))
                community = c.fetchone()
                if not community:
                    flash('Community not found', 'error')
                else:
                    community_name = community[0]

                    # Delete all related data first (cascading delete)
                    c.execute("DELETE FROM community_billing_line_items WHERE submission_id IN (SELECT id FROM community_billing_submissions WHERE community_name = ?)", (community_name,))
                    c.execute("DELETE FROM community_billing_submissions WHERE community_name = ?", (community_name,))
                    c.execute("DELETE FROM verona_walk_clock_addresses WHERE community_id = ?", (community_id,))
                    c.execute("DELETE FROM community_house_numbers WHERE community_id = ?", (community_id,))
                    c.execute("DELETE FROM community_nozzle_prices WHERE community_id = ?", (community_id,))
                    c.execute("DELETE FROM communities WHERE id = ?", (community_id,))
                    conn.commit()
                    flash(f'Community "{community_name}" deleted permanently', 'success')
            except Exception as e:
                flash(f'Error deleting community: {str(e)}', 'error')

    # Get all communities
    c.execute("SELECT id, name, created_by, created_at, active FROM communities ORDER BY name")
    communities = []
    for row in c.fetchall():
        communities.append({
            'id': row[0],
            'name': row[1],
            'created_by': row[2],
            'created_at': row[3],
            'active': row[4]
        })
    conn.close()

    return render_template_string(MANAGE_COMMUNITIES_TEMPLATE,
                                 username=session.get('username'),
                                 communities=communities)

@app.route('/community_billing_office', methods=['GET', 'POST'])
def community_billing_office():
    """Office user side - view submissions and manage communities"""
    if 'username' not in session or session.get('role') != 'office':
        return redirect(url_for('login'))

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    # Handle POST requests for adding/deleting communities
    if request.method == 'POST':
        action = request.form.get('action')

        if action == 'add':
            community_name = request.form.get('community_name', '').strip()
            try:
                num_clocks = int(request.form.get('num_clocks', 0) or 0)
            except (ValueError, TypeError):
                num_clocks = 0
            if not community_name:
                flash('Community name is required', 'error')
            elif num_clocks < 1:
                flash('Number of clocks is required (must be at least 1)', 'error')
            else:
                try:
                    c.execute("INSERT INTO communities (name, created_by, created_at, num_clocks) VALUES (?, ?, ?, ?)",
                             (community_name, session.get('username'), datetime.now().strftime('%Y-%m-%d %H:%M:%S'), num_clocks))
                    conn.commit()
                    flash(f'Community "{community_name}" added successfully', 'success')
                except sqlite3.IntegrityError:
                    flash(f'Community "{community_name}" already exists', 'error')

        elif action == 'delete':
            community_id = request.form.get('community_id')
            try:
                # Get community name first
                c.execute("SELECT name FROM communities WHERE id = ?", (community_id,))
                community = c.fetchone()
                if not community:
                    flash('Community not found', 'error')
                else:
                    community_name = community[0]

                    # Delete all related data first (cascading delete)
                    c.execute("DELETE FROM community_billing_line_items WHERE submission_id IN (SELECT id FROM community_billing_submissions WHERE community_name = ?)", (community_name,))
                    c.execute("DELETE FROM community_billing_submissions WHERE community_name = ?", (community_name,))
                    c.execute("DELETE FROM verona_walk_clock_addresses WHERE community_id = ?", (community_id,))
                    c.execute("DELETE FROM community_house_numbers WHERE community_id = ?", (community_id,))
                    c.execute("DELETE FROM community_nozzle_prices WHERE community_id = ?", (community_id,))
                    c.execute("DELETE FROM communities WHERE id = ?", (community_id,))
                    conn.commit()
                    flash(f'Community "{community_name}" deleted permanently', 'success')
            except Exception as e:
                flash(f'Error deleting community: {str(e)}', 'error')

    # Get list of active communities only
    c.execute("SELECT id, name, created_at FROM communities WHERE active = 1 ORDER BY name")
    communities = [{'id': row[0], 'name': row[1], 'created_at': row[2], 'active': True} for row in c.fetchall()]

    # Get all communities including inactive ones
    c.execute("SELECT id, name, created_at, active, COALESCE(num_clocks, 0) FROM communities ORDER BY name")
    all_communities = [{'id': row[0], 'name': row[1], 'created_at': row[2], 'active': row[3], 'num_clocks': row[4]} for row in c.fetchall()]

    conn.close()

    return render_template_string(COMMUNITY_BILLING_OFFICE_TEMPLATE,
                                 username=session.get('username'),
                                 communities=communities,
                                 all_communities=all_communities)

@app.route('/community_billing_office_data', methods=['POST'])
def community_billing_office_data():
    """Get submissions for a specific community and date"""
    if 'username' not in session or session.get('role') != 'office':
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    data = request.get_json()
    community = data.get('community')
    work_month = data.get('work_month')

    if not community or not work_month:
        return jsonify({'success': False, 'error': 'Missing community or month'})

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    # Get community ID and num_clocks to fetch pricing
    c.execute("SELECT id, COALESCE(num_clocks, 0) FROM communities WHERE name = ? AND active = 1", (community,))
    community_row = c.fetchone()
    community_id = community_row[0] if community_row else None
    comm_num_clocks = community_row[1] if community_row else 0

    # Get pricing for this community
    pricing = None
    if community_id:
        c.execute("""SELECT nozzle, pop_up_6_inch, pop_up_12_inch, rotor_6_inch,
                            new_pop_up_6_inch, new_pop_up_12_inch, riser, solenoid, stat_decoder_1
                     FROM community_nozzle_prices
                     WHERE community_id = ?""", (community_id,))
        pricing_row = c.fetchone()
        if pricing_row:
            pricing = {
                'nozzle': pricing_row[0],
                'pop_up_6_inch': pricing_row[1],
                'pop_up_12_inch': pricing_row[2],
                'rotor_6_inch': pricing_row[3],
                'new_pop_up_6_inch': pricing_row[4],
                'new_pop_up_12_inch': pricing_row[5],
                'riser': pricing_row[6],
                'solenoid': pricing_row[7],
                'stat_decoder_1': pricing_row[8]
            }

    # Get all submissions for this community and month
    c.execute("""SELECT id, tech_username, status, submitted_at
                 FROM community_billing_submissions
                 WHERE community_name = ? AND work_date LIKE ? AND status = 'submitted'
                 ORDER BY work_date DESC, submitted_at DESC""",
             (community, work_month + '%'))

    submissions = []
    total_cost = 0.0
    common_area_cost = 0.0
    clocks_cost = 0.0

    for row in c.fetchall():
        submission_id = row[0]

        # Get line items for this submission
        c.execute("""SELECT zone_and_address, nozzle, pop_up_6_inch, pop_up_12_inch,
                            rotor_6_inch, new_pop_up_6_inch, new_pop_up_12_inch,
                            riser, solenoid, stat_decoder_1, notes, COALESCE(photos, '[]')
                     FROM community_billing_line_items
                     WHERE submission_id = ?
                     ORDER BY id""", (submission_id,))

        line_items = []
        for item_row in c.fetchall():
            import json as _json
            try:
                photos_list = _json.loads(item_row[11] or '[]')
            except Exception:
                photos_list = []
            line_items.append({
                'zone_and_address': item_row[0],
                'nozzle': item_row[1],
                'pop_up_6_inch': item_row[2],
                'pop_up_12_inch': item_row[3],
                'rotor_6_inch': item_row[4],
                'new_pop_up_6_inch': item_row[5],
                'new_pop_up_12_inch': item_row[6],
                'riser': item_row[7],
                'solenoid': item_row[8],
                'stat_decoder_1': item_row[9],
                'notes': item_row[10],
                'photos': photos_list
            })

            # Calculate cost for this item if pricing is available
            if pricing:
                item_cost = (
                    (item_row[1] or 0) * pricing['nozzle'] +
                    (item_row[2] or 0) * pricing['pop_up_6_inch'] +
                    (item_row[3] or 0) * pricing['pop_up_12_inch'] +
                    (item_row[4] or 0) * pricing['rotor_6_inch'] +
                    (item_row[5] or 0) * pricing['new_pop_up_6_inch'] +
                    (item_row[6] or 0) * pricing['new_pop_up_12_inch'] +
                    (item_row[7] or 0) * pricing['riser'] +
                    (item_row[8] or 0) * pricing['solenoid'] +
                    (item_row[9] or 0) * pricing['stat_decoder_1']
                )
                total_cost += item_cost

                # Separate common area and residential costs for all communities
                zone = (item_row[0] or '').lower()
                if 'common area' in zone:
                    common_area_cost += item_cost
                else:
                    clocks_cost += item_cost

        # Derive which clocks have data entered (reuse already-fetched line_items)
        clock_nums = set()
        for item in line_items:
            total_vals = (
                (item['nozzle'] or 0) + (item['pop_up_6_inch'] or 0) +
                (item['pop_up_12_inch'] or 0) + (item['rotor_6_inch'] or 0) +
                (item['new_pop_up_6_inch'] or 0) + (item['new_pop_up_12_inch'] or 0) +
                (item['riser'] or 0) + (item['solenoid'] or 0) +
                (item['stat_decoder_1'] or 0)
            )
            has_notes = bool(item.get('notes') and str(item['notes']).strip())
            if total_vals > 0 or has_notes:
                m = re.match(r'^Clock\s+(\d+)', item['zone_and_address'] or '', re.IGNORECASE)
                if m:
                    clock_nums.add(int(m.group(1)))
        clocks_label = ', '.join(f'Clock {n}' for n in sorted(clock_nums)) if clock_nums else ''

        submissions.append({
            'id': submission_id,
            'tech_username': row[1],
            'status': row[2],
            'submitted_at': row[3],
            'line_items': line_items,
            'clocks_label': clocks_label
        })

    conn.close()

    response = {
        'success': True,
        'community': community,
        'work_month': work_month,
        'submissions': submissions,
        'total_cost': round(total_cost, 2),
        'residential_cost': round(clocks_cost, 2),
        'common_area_cost': round(common_area_cost, 2),
        'has_pricing': pricing is not None,
        'num_clocks': comm_num_clocks
    }

    return jsonify(response)

@app.route('/community_billing_export_excel', methods=['POST'])
def community_billing_export_excel():
    """Export submissions to Excel"""
    if 'username' not in session or session.get('role') != 'office':
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    except ImportError:
        return jsonify({'success': False, 'error': 'openpyxl not installed'})

    data = request.get_json()
    community = data.get('community')
    work_month = data.get('work_month')

    # Get submissions data
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    # Get community ID for pricing
    c.execute("SELECT id FROM communities WHERE name = ? AND active = 1", (community,))
    community_row = c.fetchone()
    community_id = community_row[0] if community_row else None

    # Get pricing for this community
    pricing = None
    if community_id:
        c.execute("""SELECT nozzle, pop_up_6_inch, pop_up_12_inch, rotor_6_inch,
                            new_pop_up_6_inch, new_pop_up_12_inch, riser, solenoid, stat_decoder_1
                     FROM community_nozzle_prices
                     WHERE community_id = ?""", (community_id,))
        pricing_row = c.fetchone()
        if pricing_row:
            pricing = {
                'nozzle': pricing_row[0],
                'pop_up_6_inch': pricing_row[1],
                'pop_up_12_inch': pricing_row[2],
                'rotor_6_inch': pricing_row[3],
                'new_pop_up_6_inch': pricing_row[4],
                'new_pop_up_12_inch': pricing_row[5],
                'riser': pricing_row[6],
                'solenoid': pricing_row[7],
                'stat_decoder_1': pricing_row[8]
            }

    c.execute("""SELECT id, tech_username, status, submitted_at
                 FROM community_billing_submissions
                 WHERE community_name = ? AND work_date LIKE ? AND status = 'submitted'
                 ORDER BY work_date DESC, submitted_at DESC""",
             (community, work_month + '%'))

    submissions = []
    total_cost = 0.0
    for row in c.fetchall():
        submission_id = row[0]

        c.execute("""SELECT zone_and_address, nozzle, pop_up_6_inch, pop_up_12_inch,
                            rotor_6_inch, new_pop_up_6_inch, new_pop_up_12_inch,
                            riser, solenoid, stat_decoder_1
                     FROM community_billing_line_items
                     WHERE submission_id = ?
                     ORDER BY id""", (submission_id,))

        line_items = []
        for item_row in c.fetchall():
            item_dict = {
                'zone_and_address': item_row[0] or '',
                'nozzle': item_row[1] or 0,
                'pop_up_6_inch': item_row[2] or 0,
                'pop_up_12_inch': item_row[3] or 0,
                'rotor_6_inch': item_row[4] or 0,
                'new_pop_up_6_inch': item_row[5] or 0,
                'new_pop_up_12_inch': item_row[6] or 0,
                'riser': item_row[7] or 0,
                'solenoid': item_row[8] or 0,
                'stat_decoder_1': item_row[9] or 0
            }

            # Calculate cost for this item if pricing is available
            if pricing:
                item_cost = (
                    (item_row[1] or 0) * pricing['nozzle'] +
                    (item_row[2] or 0) * pricing['pop_up_6_inch'] +
                    (item_row[3] or 0) * pricing['pop_up_12_inch'] +
                    (item_row[4] or 0) * pricing['rotor_6_inch'] +
                    (item_row[5] or 0) * pricing['new_pop_up_6_inch'] +
                    (item_row[6] or 0) * pricing['new_pop_up_12_inch'] +
                    (item_row[7] or 0) * pricing['riser'] +
                    (item_row[8] or 0) * pricing['solenoid'] +
                    (item_row[9] or 0) * pricing['stat_decoder_1']
                )
                item_dict['cost'] = item_cost
                total_cost += item_cost
            else:
                item_dict['cost'] = 0

            line_items.append(item_dict)

        submissions.append({
            'tech_username': row[1],
            'submitted_at': row[3],
            'line_items': line_items
        })

    conn.close()

    # Create Excel workbook
    try:
        wb = Workbook()
        ws = wb.active
        ws.title = "Submissions"

        # Set up styles
        header_font = Font(bold=True, color="FFFFFF", size=12)
        header_fill = PatternFill(start_color="4472C4", end_color="4472C4", fill_type="solid")
        summary_fill = PatternFill(start_color="E2EFDA", end_color="E2EFDA", fill_type="solid")
        summary_font = Font(bold=True, size=11)
        border = Border(
            left=Side(style='thin'),
            right=Side(style='thin'),
            top=Side(style='thin'),
            bottom=Side(style='thin')
        )
        center_align = Alignment(horizontal='center', vertical='center')
        currency_format = '$#,##0.00'

        # Title
        ws.merge_cells('A1:J1')
        title_cell = ws['A1']
        title_cell.value = f"Community Maintenance Report - {community} ({work_month})"
        title_cell.font = Font(bold=True, size=14)
        title_cell.alignment = center_align
        ws.row_dimensions[1].height = 25

        current_row = 3

        # Add submissions
        for submission in submissions:
            # Tech name header
            ws.merge_cells(f'A{current_row}:J{current_row}')
            tech_cell = ws[f'A{current_row}']
            tech_cell.value = f"Tech: {submission['tech_username']} (Submitted: {submission['submitted_at']})"
            tech_cell.font = Font(bold=True, size=11)
            tech_cell.fill = PatternFill(start_color="D9E8F5", end_color="D9E8F5", fill_type="solid")
            ws.row_dimensions[current_row].height = 18
            current_row += 1

            # Column headers
            headers = ['Zone & Address', 'Nozzle', '6" Pop Up', '12" Pop Up', '6" Rotor',
                      'NEW 6" Pop Up', 'NEW 12" Pop Up', 'Riser', 'Solenoid', '1 Stat Decoder']
            if pricing:
                headers.append('Item Cost')

            for col_num, header in enumerate(headers, 1):
                cell = ws.cell(row=current_row, column=col_num)
                cell.value = header
                cell.font = header_font
                cell.fill = header_fill
                cell.alignment = center_align
                cell.border = border

            ws.row_dimensions[current_row].height = 20
            current_row += 1

            # Data rows
            for item in submission['line_items']:
                ws.cell(row=current_row, column=1).value = item['zone_and_address']
                ws.cell(row=current_row, column=2).value = item['nozzle']
                ws.cell(row=current_row, column=3).value = item['pop_up_6_inch']
                ws.cell(row=current_row, column=4).value = item['pop_up_12_inch']
                ws.cell(row=current_row, column=5).value = item['rotor_6_inch']
                ws.cell(row=current_row, column=6).value = item['new_pop_up_6_inch']
                ws.cell(row=current_row, column=7).value = item['new_pop_up_12_inch']
                ws.cell(row=current_row, column=8).value = item['riser']
                ws.cell(row=current_row, column=9).value = item['solenoid']
                ws.cell(row=current_row, column=10).value = item['stat_decoder_1']

                if pricing:
                    cost_cell = ws.cell(row=current_row, column=11)
                    cost_cell.value = item['cost']
                    cost_cell.number_format = currency_format

                # Apply borders and center alignment to numeric columns
                for col in range(2, 11):
                    cell = ws.cell(row=current_row, column=col)
                    cell.alignment = center_align
                    cell.border = border

                current_row += 1

            current_row += 1

        # Add total cost summary at the end
        if pricing:
            current_row += 1
            ws.merge_cells(f'A{current_row}:J{current_row}')
            summary_label = ws[f'A{current_row}']
            summary_label.value = "TOTAL COST FOR ALL PARTS"
            summary_label.font = summary_font
            summary_label.fill = summary_fill
            summary_label.alignment = center_align
            summary_label.border = border
            current_row += 1

            ws.merge_cells(f'A{current_row}:J{current_row}')
            total_cell = ws[f'A{current_row}']
            total_cell.value = total_cost
            total_cell.font = Font(bold=True, size=14, color="2E7D32")
            total_cell.number_format = currency_format
            total_cell.fill = summary_fill
            total_cell.alignment = center_align
            total_cell.border = border
            ws.row_dimensions[current_row].height = 25

        # Adjust column widths
        ws.column_dimensions['A'].width = 20
        for col in ['B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J', 'K']:
            ws.column_dimensions[col].width = 15

        # Save file
        excel_filename = f"community_billing_{community.replace(' ', '_')}_{work_month}.xlsx"
        excel_path = os.path.join(app.config['UPLOAD_FOLDER'], excel_filename)
        wb.save(excel_path)

        return jsonify({
            'success': True,
            'download_url': f'/download_file/{excel_filename}'
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})

@app.route('/community_billing_delete_submission', methods=['POST'])
def community_billing_delete_submission():
    """Delete a submission and all its related line items"""
    if 'username' not in session or session.get('role') != 'office':
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    try:
        data = request.get_json()
        submission_id = data.get('submission_id')

        if not submission_id:
            return jsonify({'success': False, 'error': 'Missing submission_id'})

        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()

        # Delete all line items for this submission
        c.execute("DELETE FROM community_billing_line_items WHERE submission_id = ?", (submission_id,))

        # Delete the submission itself
        c.execute("DELETE FROM community_billing_submissions WHERE id = ?", (submission_id,))

        conn.commit()
        conn.close()

        return jsonify({'success': True, 'message': 'Submission deleted successfully'})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})

