@app.route('/community_house_numbers', methods=['GET'])
def community_house_numbers():
    """Get house numbers for a community"""
    # Allow both office and tech users
    if 'username' not in session or session.get('role') not in ['office', 'technician']:
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    community_id = request.args.get('community_id')
    if not community_id:
        return jsonify({'success': False, 'error': 'Missing community_id'})

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    c.execute("""SELECT id, house_number, created_at
                 FROM community_house_numbers
                 WHERE community_id = ?
                 ORDER BY house_number""", (community_id,))

    house_numbers = [{'id': row[0], 'house_number': row[1], 'created_at': row[2]} for row in c.fetchall()]
    conn.close()

    return jsonify({'success': True, 'house_numbers': house_numbers})

@app.route('/community_add_house_number', methods=['POST'])
def community_add_house_number():
    """Add a new house number to a community"""
    if 'username' not in session or session.get('role') != 'office':
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    data = request.get_json()
    community_id = data.get('community_id')
    house_number = data.get('house_number', '').strip()

    if not community_id or not house_number:
        return jsonify({'success': False, 'error': 'Missing required fields'})

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    try:
        c.execute("""INSERT INTO community_house_numbers
                     (community_id, house_number, created_at)
                     VALUES (?, ?, ?)""",
                 (community_id, house_number, datetime.now().strftime('%Y-%m-%d %H:%M:%S')))

        # Sync drafts with updated addresses
        c.execute("SELECT name FROM communities WHERE id = ?", (community_id,))
        community_row = c.fetchone()
        if community_row:
            sync_community_drafts(c, community_row[0], community_id)

        conn.commit()
        return jsonify({'success': True, 'message': 'House number added successfully'})
    except sqlite3.IntegrityError:
        return jsonify({'success': False, 'error': 'This house number already exists in this community'})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})
    finally:
        conn.close()

@app.route('/community_delete_house_number', methods=['POST'])
def community_delete_house_number():
    """Delete a house number"""
    if 'username' not in session or session.get('role') != 'office':
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    data = request.get_json()
    house_number_id = data.get('house_number_id')

    if not house_number_id:
        return jsonify({'success': False, 'error': 'Missing house_number_id'})

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    try:
        # Get community info before deleting
        c.execute("""SELECT chn.community_id, com.name
                     FROM community_house_numbers chn
                     JOIN communities com ON com.id = chn.community_id
                     WHERE chn.id = ?""", (house_number_id,))
        info = c.fetchone()

        c.execute("DELETE FROM community_house_numbers WHERE id = ?", (house_number_id,))

        # Sync drafts with updated addresses
        if info:
            sync_community_drafts(c, info[1], info[0])

        conn.commit()
        return jsonify({'success': True, 'message': 'House number deleted successfully'})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})
    finally:
        conn.close()

# ============================================================================
# SHARED HELPER: ZONE / ADDRESS COLUMN DETECTION
# ============================================================================

def _detect_zone_station_layout(all_rows):
    """Detect zone-number and address/station columns from worksheet rows.

    Strategies tried in order:

    1. Sequential-integer scan (format-agnostic, most reliable)
       Zone columns *always* contain sequential integers starting near 1
       (1, 2, 3 …).  No column labels needed.  Address columns are then
       identified by content: varied values, not times, not single-char
       repetitions, and either large house numbers (>999) or meaningful text.

    2. Header keyword scan
       Fallback when the sheet has labelled headers but sequential detection
       failed (e.g. zones starting above 10, very short lists).

    3. Single-column  "N – description"  pattern.

    4. Hard default: column 0 = zone, column 1 = station.

    Returns a dict:
        zone_col        int (0-based) or None in single_col_mode
        station_col     int (0-based) or None in single_col_mode
        data_start_row  int row index where data rows begin
        single_col_mode bool
        extra_cols      list[int] – additional address columns to concatenate
    """
    SINGLE_COL_RE = re.compile(r'^(\d+)\s*[-\u2013\u2014]\s*(.+)$')
    max_cols = max((len(r) for r in all_rows), default=0)

    # ------------------------------------------------------------------
    # Strategy 1: Sequential integers → zone col; content scoring → addr cols
    # ------------------------------------------------------------------
    if max_cols >= 2:
        col_int_vals  = [[] for _ in range(max_cols)]  # integers 1-999 per col
        col_all_vals  = [[] for _ in range(max_cols)]  # every non-None value

        for row in all_rows[:200]:
            for ci, cell in enumerate(row):
                v = cell.value
                if v is None:
                    continue
                col_all_vals[ci].append(v)
                # Skip long strings (sheet titles, notes) from zone counting
                if isinstance(v, str) and len(v.split()) > 4:
                    continue
                n = _extract_zone_num(v)
                if n is not None:
                    col_int_vals[ci].append(n)

        # Score each column: high score = sequential integers starting near 1
        zone_col        = None
        best_zone_score = 0.0
        for ci in range(max_cols):
            ints = col_int_vals[ci]
            if len(ints) < 2:
                continue
            sorted_u = sorted(set(ints))
            min_v, max_v = sorted_u[0], sorted_u[-1]
            if min_v > 10:           # zone sequences start near 1
                continue
            expected  = set(range(min_v, max_v + 1))
            coverage  = len(set(sorted_u) & expected) / max(len(expected), 1)
            score     = coverage * (1.0 if min_v == 1 else 0.8)
            if score > best_zone_score:
                best_zone_score, zone_col = score, ci

        if zone_col is not None and best_zone_score >= 0.6:
            # data_start_row = first row where zone_col holds its minimum integer
            min_zone   = min(col_int_vals[zone_col])
            data_start = 0
            for ri, row in enumerate(all_rows):
                if len(row) > zone_col and row[zone_col].value is not None:
                    v = row[zone_col].value
                    # Skip title-like rows (e.g. "SPANISH WELLS CLOCK # 4")
                    if isinstance(v, str) and len(v.split()) > 4:
                        continue
                    if _extract_zone_num(v) == min_zone:
                        data_start = ri
                        break

            # Score every other column for "address-ness"
            addr_cols = []
            for ci in range(max_cols):
                if ci == zone_col:
                    continue
                vals = col_all_vals[ci]
                if len(vals) < 2:
                    continue
                n = len(vals)

                time_count = sum(
                    1 for v in vals
                    if (isinstance(v, float) and 0 < v < 1)
                    or (isinstance(v, str) and re.match(r'^\d{1,2}:\d{2}', v.strip()))
                )
                large_num_count = sum(
                    1 for v in vals
                    if _is_large_int(v)
                )
                text_count = sum(
                    1 for v in vals
                    if isinstance(v, str) and sum(c.isalpha() for c in v) > 2
                )
                single_char_count = sum(
                    1 for v in vals
                    if isinstance(v, str) and len(v.strip()) == 1
                )
                unique_ratio     = len({str(v) for v in vals}) / n
                time_ratio       = time_count        / n
                large_num_ratio  = large_num_count   / n
                text_ratio       = text_count        / n
                single_char_ratio = single_char_count / n

                if time_ratio > 0.4:           # time columns (start/end time)
                    continue
                if single_char_ratio > 0.7:    # single-char cols (A/B/C, clock)
                    continue
                # Low-variety categorical columns (SPRAYS / T/TH/SUN / PROGRAM)
                if unique_ratio < 0.08 and large_num_ratio < 0.3:
                    continue
                # Reject columns where one value dominates (e.g. "SPRAY 20 MINS" × 22 rows)
                val_strs = [str(v).upper().strip() for v in vals]
                most_common_freq = max(val_strs.count(s) for s in set(val_strs)) / n
                if most_common_freq > 0.5 and large_num_ratio < 0.3:
                    continue
                # Include: house-number column OR varied text column
                if large_num_ratio > 0.3 or (text_ratio > 0.3 and unique_ratio >= 0.08):
                    addr_cols.append(ci)

            if addr_cols:
                return {
                    'zone_col':       zone_col,
                    'station_col':    addr_cols[0],
                    'data_start_row': data_start,
                    'single_col_mode': False,
                    'extra_cols':     addr_cols[1:],
                }

    # ------------------------------------------------------------------
    # Strategy 2: Header keyword scan (fallback for labelled sheets)
    # ------------------------------------------------------------------
    ZONE_KW = {
        'zone', 'z#', 'zn', 'zn#', 'zone#', 'zone #', 'zone no', 'zone no.',
        'zone number', 'zone num', 'sta', 'sta#', 'sta #', 'sta no', 'sta no.',
        'station no', 'station#', 'station #', 'station number', 'station num',
        'stn', 'stn#', 'clk', 'clk#',
    }
    ADDR_KW = {
        'station', 'address', 'name', 'description', 'desc', 'location',
        'street', 'lot', 'unit', 'house', 'addr', 'property', 'site',
        'label', 'detail',
    }
    for row_idx, row in enumerate(all_rows[:15]):
        row_vals = [
            str(c.value).lower().strip() if c.value is not None else ''
            for c in row
        ]
        z_col = s_col = None
        for i, v in enumerate(row_vals):
            if not v:
                continue
            v_words       = set(v.split())
            is_zone_exact = v in ZONE_KW
            is_addr_exact = v in ADDR_KW
            is_zone_word  = bool(v_words & ZONE_KW)
            is_addr_word  = bool(v_words & ADDR_KW)
            if z_col is None:
                if is_zone_exact or (is_zone_word and not is_addr_word):
                    z_col = i
            elif s_col is None:
                if is_addr_exact or (is_addr_word and not is_zone_word):
                    s_col = i
        if z_col is not None and s_col is not None and z_col != s_col:
            extra_cols = []
            for j, v2 in enumerate(row_vals):
                if j in (z_col, s_col) or not v2:
                    continue
                v2_words = set(v2.split())
                if (v2 in ADDR_KW) or (bool(v2_words & ADDR_KW) and not bool(v2_words & ZONE_KW)):
                    extra_cols.append(j)
            return {
                'zone_col':       z_col,
                'station_col':    s_col,
                'data_start_row': row_idx + 1,
                'single_col_mode': False,
                'extra_cols':     extra_cols,
            }

    # ------------------------------------------------------------------
    # Strategy 3: single-column "N – description"
    # ------------------------------------------------------------------
    for row in all_rows:
        for ci in range(min(3, len(row))):
            if row[ci].value is not None:
                if SINGLE_COL_RE.match(str(row[ci].value).strip()):
                    return {
                        'zone_col':       None,
                        'station_col':    None,
                        'data_start_row': 0,
                        'single_col_mode': True,
                        'extra_cols':     [],
                    }

    # ------------------------------------------------------------------
    # Strategy 4: default
    # ------------------------------------------------------------------
    return {
        'zone_col':       0,
        'station_col':    1,
        'data_start_row': 0,
        'single_col_mode': False,
        'extra_cols':     [],
    }


def _is_large_int(v):
    """Return True if v converts to an integer > 999 (house-number range)."""
    try:
        return int(float(v)) > 999
    except (ValueError, TypeError):
        return False


# Matches trailing integer in "STATION # 1", "STATION #20", "STATION # 1 SP", "ZONE 5", etc.
# The first branch allows one optional short word after the number (e.g. "SP", "S", "A")
# so that suffixes like "STATION # 1 SP" are handled correctly.
_EMBEDDED_INT_RE = re.compile(r'#\s*(\d+)(?:\s+\w{1,5})?$|(?<!\d)(\d+)\s*$')


def _extract_zone_num(v):
    """Extract an integer zone number (1-999) from v.

    Handles plain numbers as well as text like 'STATION # 1' or 'ZONE 5'.
    Returns None if no zone number can be found.
    """
    try:
        n = int(float(v))
        return n if 1 <= n <= 999 else None
    except (ValueError, TypeError):
        pass
    if isinstance(v, str):
        m = _EMBEDDED_INT_RE.search(v.strip())
        if m:
            try:
                n = int(m.group(1) or m.group(2))
                return n if 1 <= n <= 999 else None
            except (TypeError, ValueError):
                pass
    return None


# ============================================================================
# COMMUNITY HOUSE NUMBER EXCEL IMPORT
# ============================================================================

@app.route('/community_import_house_numbers_excel', methods=['POST'])
def community_import_house_numbers_excel():
    """Parse an Excel file to extract house numbers for a standard community.

    Reads CLOCK sheets (named 'CLOCK N') from the uploaded Excel file,
    auto-detects the Zone and Description/Station columns from the header row,
    and formats each entry as "ZONE {n} - {description}".
    Non-CLOCK sheets are also parsed and grouped as clock 0 ("Other Entries").
    Returns data grouped by clock for the preview/review UI.
    """
    if 'username' not in session or session.get('role') != 'office':
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    try:
        from openpyxl import load_workbook
    except ImportError:
        return jsonify({'success': False, 'error': 'openpyxl not installed'})

    community_id = request.form.get('community_id')
    if not community_id:
        return jsonify({'success': False, 'error': 'Missing community_id'})

    file = request.files.get('file')
    if not file or not file.filename.endswith(('.xlsx', '.xls')):
        return jsonify({'success': False, 'error': 'Please upload a valid Excel file (.xlsx or .xls)'})

    use_common_area = request.form.get('use_common_area') == '1'

    try:
        wb = load_workbook(file, data_only=True)
    except Exception as e:
        return jsonify({'success': False, 'error': f'Could not read Excel file: {str(e)}'})

    COMMON_AREA_KEYWORDS = ['ROTORS', 'SIDEWALK', 'LAKE BANK', 'COMMON AREA', 'CUL D SAC', 'CUL DE SAC', 'PUMP']

    def is_common_area_entry(text):
        t = text.upper().strip()
        if t.startswith('ROTORS'):
            return True
        for kw in COMMON_AREA_KEYWORDS[1:]:
            if kw in t:
                return True
        return False

    results = {}
    total_addresses = 0
    total_common_area = 0

    for sheet_name in wb.sheetnames:
        match = re.match(r'CLOCK\s*(\d+)', sheet_name.strip(), re.IGNORECASE)
        clock_number = int(match.group(1)) if match else 0

        ws = wb[sheet_name]
        addresses = []
        common_area = []

        all_rows        = list(ws.iter_rows(min_row=1, values_only=False))
        layout          = _detect_zone_station_layout(all_rows)
        zone_col        = layout['zone_col']
        station_col     = layout['station_col']
        data_start_row  = layout['data_start_row']
        single_col_mode = layout['single_col_mode']
        extra_cols      = layout.get('extra_cols', [])
        SINGLE_COL_RE   = re.compile(r'^(\d+)\s*[-\u2013\u2014]\s*(.+)$')
        SKIP_VALUES     = {'nonexistent', 'n/a', 'na', 'none', 'tbd', '-'}

        for row in all_rows[data_start_row:]:
            if single_col_mode:
                cell_val = row[0].value if len(row) > 0 else None
                if cell_val is None:
                    continue
                m = SINGLE_COL_RE.match(str(cell_val).strip())
                if not m:
                    continue
                zone_num = int(m.group(1))
                station = m.group(2).strip()
                if not station:
                    continue
            else:
                zone_cell = row[zone_col].value if len(row) > zone_col else None
                zone_num = _extract_zone_num(zone_cell) if zone_cell is not None else None
                if zone_num is None:
                    continue  # skip header rows, totals, blank rows, etc.

                station = str(station_cell).strip()
                if not station or station.lower() in SKIP_VALUES:
                    continue

                # Concatenate extra address columns (e.g. Street after House Number)
                for ec in extra_cols:
                    if len(row) > ec and row[ec].value is not None:
                        extra_str = str(row[ec].value).strip()
                        if extra_str and extra_str.lower() not in SKIP_VALUES:
                            station = f"{station} {extra_str}"

            formatted = f"ZONE {zone_num} - {station}"

            if use_common_area and is_common_area_entry(station):
                common_area.append(formatted)
                total_common_area += 1
            else:
                addresses.append(formatted)
                total_addresses += 1

        if addresses or common_area:
            if clock_number in results:
                results[clock_number]['addresses'].extend(addresses)
                results[clock_number]['common_area'].extend(common_area)
            else:
                results[clock_number] = {'addresses': addresses, 'common_area': common_area}

    if not results:
        return jsonify({'success': False, 'error': 'No valid address data found. Check that sheets have Zone and Station/Address columns, or use single-column format "1 -DESCRIPTION".'})

    preview_data = {str(k): results[k] for k in sorted(results.keys())}
    return jsonify({
        'success': True,
        'clocks': preview_data,
        'total_addresses': total_addresses,
        'total_common_area': total_common_area,
        'total': total_addresses + total_common_area
    })


@app.route('/community_import_house_numbers_confirmed', methods=['POST'])
def community_import_house_numbers_confirmed():
    """Import the user-reviewed house numbers into a standard community."""
    if 'username' not in session or session.get('role') != 'office':
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    data = request.get_json()
    community_id = data.get('community_id')
    house_numbers = data.get('house_numbers', [])

    if not community_id or not house_numbers:
        return jsonify({'success': False, 'error': 'Missing required fields'})

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    try:
        added = 0
        skipped = 0
        inserted_ids = []
        for house_number in house_numbers:
            house_number = str(house_number).strip()
            if not house_number:
                continue
            try:
                c.execute("""INSERT INTO community_house_numbers
                             (community_id, house_number, created_at)
                             VALUES (?, ?, ?)""",
                         (community_id, house_number, datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
                inserted_ids.append(c.lastrowid)
                added += 1
            except sqlite3.IntegrityError:
                skipped += 1  # Duplicate - already exists

        # Sync drafts with updated addresses
        if added > 0:
            c.execute("SELECT name FROM communities WHERE id = ?", (community_id,))
            community_row = c.fetchone()
            if community_row:
                sync_community_drafts(c, community_row[0], community_id)

        conn.commit()
        msg = f'Successfully imported {added} house numbers'
        if skipped > 0:
            msg += f' ({skipped} duplicates skipped)'
        return jsonify({'success': True, 'message': msg, 'imported': added, 'skipped': skipped,
                        'inserted_ids': inserted_ids, 'import_type': 'house_numbers'})
    except Exception as e:
        conn.rollback()
        return jsonify({'success': False, 'error': str(e)})
    finally:
        conn.close()


# ============================================================================
# VERONA WALK HOA CLOCK ROUTES
# ============================================================================

@app.route('/verona_walk_clocks', methods=['GET'])
def verona_walk_clocks():
    """Get clock addresses for Verona Walk HOA"""
    if 'username' not in session or session.get('role') not in ['office', 'technician']:
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    community_id = request.args.get('community_id')
    if not community_id:
        return jsonify({'success': False, 'error': 'Missing community_id'})

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    c.execute("SELECT COALESCE(num_clocks, 0) FROM communities WHERE id = ?", (community_id,))
    clocks_row = c.fetchone()
    num_clocks = clocks_row[0] if clocks_row else 0

    if num_clocks == 0:
        c.execute("SELECT MAX(clock_number) FROM verona_walk_clock_addresses WHERE community_id = ?", (community_id,))
        max_row = c.fetchone()
        num_clocks = max_row[0] if max_row and max_row[0] else 0

    # Build the clock structure with addresses
    clocks = []

    for i in range(1, num_clocks + 1):
        clocks.append({
            'clock_number': i,
            'clock_label': f'Clock {i}',
            'addresses': []
        })

    # Fetch all addresses for this community
    c.execute("""SELECT id, clock_number, address, COALESCE(is_common_area, 0)
                 FROM verona_walk_clock_addresses
                 WHERE community_id = ?
                 ORDER BY clock_number, is_common_area, sort_order, id""", (community_id,))

    addresses = c.fetchall()

    # Add common_area_addresses list to each clock
    for clock in clocks:
        clock['common_area_addresses'] = []

    # Organize addresses by clock and type
    for addr_id, clock_num, address, is_ca in addresses:
        for clock in clocks:
            if clock['clock_number'] == clock_num:
                entry = {'id': addr_id, 'address': address, 'is_common_area': bool(is_ca)}
                if is_ca:
                    clock['common_area_addresses'].append(entry)
                else:
                    clock['addresses'].append(entry)
                break

    conn.close()
    return jsonify({'success': True, 'clocks': clocks})

@app.route('/verona_walk_add_address', methods=['POST'])
def verona_walk_add_address():
    """Add an address to a clock in Verona Walk HOA"""
    if 'username' not in session or session.get('role') != 'office':
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    data = request.get_json()
    community_id = data.get('community_id')
    clock_number = data.get('clock_number')
    address = data.get('address', '').strip()
    is_common_area = data.get('is_common_area', 0)

    if not community_id or clock_number is None or not address:
        return jsonify({'success': False, 'error': 'Missing required fields'})

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    try:
        # Get next sort_order
        c.execute("""SELECT COALESCE(MAX(sort_order), 0) + 1 FROM verona_walk_clock_addresses
                     WHERE community_id = ? AND clock_number = ? AND is_common_area = ?""",
                 (community_id, clock_number, is_common_area))
        next_order = c.fetchone()[0]
        c.execute("""INSERT INTO verona_walk_clock_addresses
                     (community_id, clock_number, address, created_at, is_common_area, sort_order)
                     VALUES (?, ?, ?, ?, ?, ?)""",
                 (community_id, clock_number, address, datetime.now().strftime('%Y-%m-%d %H:%M:%S'), is_common_area, next_order))

        # Sync drafts with updated addresses
        sync_community_drafts(c, 'Verona Walk HOA', community_id)

        conn.commit()
        return jsonify({'success': True, 'message': 'Address added successfully'})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})
    finally:
        conn.close()

@app.route('/verona_walk_bulk_add_addresses', methods=['POST'])
def verona_walk_bulk_add_addresses():
    """Bulk add addresses to a clock (supports paste from Excel)"""
    if 'username' not in session or session.get('role') != 'office':
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    data = request.get_json()
    community_id = data.get('community_id')
    clock_number = data.get('clock_number')
    addresses = data.get('addresses', [])
    is_common_area = data.get('is_common_area', 0)

    if not community_id or clock_number is None or not addresses:
        return jsonify({'success': False, 'error': 'Missing required fields'})

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    try:
        # Get next sort_order
        c.execute("""SELECT COALESCE(MAX(sort_order), 0) FROM verona_walk_clock_addresses
                     WHERE community_id = ? AND clock_number = ? AND is_common_area = ?""",
                 (community_id, clock_number, is_common_area))
        next_order = c.fetchone()[0] + 1
        added = 0
        for address in addresses:
            address = address.strip()
            if address:
                c.execute("""INSERT INTO verona_walk_clock_addresses
                             (community_id, clock_number, address, created_at, is_common_area, sort_order)
                             VALUES (?, ?, ?, ?, ?, ?)""",
                         (community_id, clock_number, address,
                          datetime.now().strftime('%Y-%m-%d %H:%M:%S'), is_common_area, next_order))
                next_order += 1
                added += 1

        # Sync drafts with updated addresses
        if added > 0:
            sync_community_drafts(c, 'Verona Walk HOA', community_id)

        conn.commit()
        return jsonify({'success': True, 'message': f'{added} address(es) added successfully'})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})
    finally:
        conn.close()

@app.route('/verona_walk_insert_address', methods=['POST'])
def verona_walk_insert_address():
    """Insert address(es) after a specific address to maintain order"""
    if 'username' not in session or session.get('role') != 'office':
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    data = request.get_json()
    after_id = data.get('after_id')
    addresses = data.get('addresses', [])

    if not after_id or not addresses:
        return jsonify({'success': False, 'error': 'Missing required fields'})

    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    try:
        # Get the reference address details
        c.execute("""SELECT community_id, clock_number, is_common_area, sort_order
                     FROM verona_walk_clock_addresses WHERE id = ?""", (after_id,))
        ref = c.fetchone()
        if not ref:
            return jsonify({'success': False, 'error': 'Reference address not found'})

        community_id, clock_number, is_common_area, ref_order = ref
        count = len([a for a in addresses if a.strip()])

        # Shift all addresses after the reference point to make room
        c.execute("""UPDATE verona_walk_clock_addresses
                     SET sort_order = sort_order + ?
                     WHERE community_id = ? AND clock_number = ? AND is_common_area = ?
                       AND sort_order > ?""",
                 (count, community_id, clock_number, is_common_area, ref_order))

        # Insert the new addresses
        added = 0
        for address in addresses:
            address = address.strip()
            if address:
                added += 1
                c.execute("""INSERT INTO verona_walk_clock_addresses
                             (community_id, clock_number, address, created_at, is_common_area, sort_order)
                             VALUES (?, ?, ?, ?, ?, ?)""",
                         (community_id, clock_number, address,
                          datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                          is_common_area, ref_order + added))

        # Sync drafts with updated addresses
        if added > 0:
            sync_community_drafts(c, 'Verona Walk HOA', community_id)

        conn.commit()
        return jsonify({'success': True, 'message': f'{added} address(es) inserted'})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})
    finally:
        conn.close()

@app.route('/verona_walk_move_addresses', methods=['POST'])
def verona_walk_move_addresses():
    """Move addresses between Addresses and Common Area"""
    if 'username' not in session or session.get('role') != 'office':
        return jsonify({'success': False, 'error': 'Access denied'}), 401

    data = request.get_json()
